export const meta = {
  name: 'stacked-fix-pr',
  description: 'Implement one stacked fix PR: sequential tasks, then review with real checks and a fix round',
  phases: [
    { title: 'Implement', detail: 'one task at a time, each committed with its own tests' },
    { title: 'Review', detail: 'reviewer runs clippy and tests on the whole diff' },
    { title: 'Fix', detail: 'address review findings' },
  ],
}

const A = args
const COMMON = `
Worktree: ${A.wt} (branch ${A.branch}, base ${A.base}). Work ONLY there: cd into it in every Bash call. The main checkout at /Users/gabe/Projects/callisto is used by other sessions: never touch it.
Build env: always prefix cargo with CARGO_TARGET_DIR=${A.target}. You are the only agent building right now; run one cargo command at a time, scoped (cargo test -p <crate> [filter], cargo clippy -p <crate> --all-targets -- -D warnings). cargo nextest is available.
Context: ${A.wt}/docs/projects/ROAD-TO-V1.md section "${A.section}" (the plan and owner decisions), the spec(s) ${A.specs.join(', ')}, .claude/semantic-model/INDEX.md and its topic files for this area, docs/adr/.
Rules: follow AGENTS.md (format-preserving edits, atomic_write, miette codes with help, grep for sibling defects and fix them in the same change, code never cites specs, one-line comments only for a non-obvious why). Update the spec criteria that change, in the same commit, current behavior only, no history. When the task implements an owner decision listed in the roadmap, add a short ADR in docs/adr (next number; format: # N. Title / Context / Decision / Consequences) and a row in docs/adr/README.md.
Commit: conventional commit message explaining why; no trailers, no session links, no Co-Authored-By. Add a changeset first when the change is user-visible: \`CARGO_TARGET_DIR=${A.target} cargo run -q -p callisto-cli -- add --package callisto-cli:patch --summary "..."\` (plain, one or two sentences, user-facing).
Reproduction fixtures from the evaluation (if referenced) are in ${A.repro}; the prebuilt 0.8.0 binary is ${A.target}/debug/callisto only until you rebuild it.
`

const RESULT = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['done', 'blocked'] },
    commit: { type: 'string' },
    summary: { type: 'string' },
    tests: { type: 'string', description: 'commands run and pass/fail counts' },
    spec_changes: { type: 'string' },
    deferred: { type: 'string', description: 'anything not done and why' },
  },
  required: ['status', 'summary', 'tests'],
}

phase('Implement')
const results = []
for (const [i, t] of A.tasks.entries()) {
  const r = await agent(`${COMMON}\nTask ${i + 1}/${A.tasks.length}: ${t.title}\n${t.detail}\n\nDone when: the fix is in, a test fails without it and passes with it, the crate's scoped tests and clippy pass, and one commit is made on ${A.branch}. If something in the task is wrong on inspection, say so in 'deferred' instead of forcing it.`,
    { label: `task:${t.key}`, phase: 'Implement', agentType: 'smith:implementer', schema: RESULT })
  results.push({ key: t.key, ...(r || { status: 'blocked', summary: 'agent died', tests: '' }) })
  log(`${t.key}: ${r ? r.status : 'died'}`)
}

phase('Review')
const REVIEW = {
  type: 'object',
  properties: {
    issues: { type: 'array', items: { type: 'object', properties: {
      severity: { type: 'string', enum: ['blocker', 'should-fix', 'nit'] },
      file: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } },
      required: ['severity', 'problem', 'fix'] } },
    checks_run: { type: 'string', description: 'exact commands actually executed and their results' },
  },
  required: ['issues', 'checks_run'],
}
const review = await agent(`${COMMON}\nReview the whole diff \`git -C ${A.wt} diff ${A.base}...HEAD\` for this PR ("${A.section}"). Implementer reports:\n${JSON.stringify(results, null, 1)}\n\nCheck: each roadmap item for this PR is actually fixed (reproduce with the fixtures or a test), no sibling left behind, spec criteria match the new behavior, tests would fail without the fix, no scope creep. ACTUALLY RUN: cargo clippy on each touched crate with -D warnings, and cargo nextest run -p on each touched crate; report real output. Do not edit files.`,
  { label: 'review', phase: 'Review', agentType: 'smith:reviewer', schema: REVIEW })

const todo = (review?.issues || []).filter(x => x.severity !== 'nit')
let fix = null
if (todo.length) {
  phase('Fix')
  fix = await agent(`${COMMON}\nAddress these review findings in one or more commits on ${A.branch}:\n${JSON.stringify(todo, null, 1)}\nReject a finding only with evidence (say why in 'deferred').`,
    { label: 'fix', phase: 'Fix', agentType: 'smith:implementer', schema: RESULT })
}
return { results, review, fix }

