    fn github_api_observation_parser_requires_an_explicit_http_status() {
        let response = parse_github_api_response(
            "gh",
            &["api"],
            "HTTP/2 404\r\ncontent-type: application/json\r\n\r\n{\"message\":\"Not Found\"}",
        )
